import torch
import torch.nn.functional as F
@torch.no_grad()
def teacher_logits(model_t, x, rubric_ids):
    return model_t(x=x, rubric=rubric_ids).logits
def rp_opd_loss(model_s, x, t_logits):
    s_logits = model_s(x=x).logits
    p_t = F.softmax(t_logits, -1)          # 教师(带 rubric)
    log_p_s = F.log_softmax(s_logits, -1)  # 学生(无 rubric)
    return F.kl_div(log_p_s, p_t, reduction='batchmean')

import torch
def kl_penalty(logp, logp_ref):
    return (logp.exp() * (logp - logp_ref)).sum(-1).mean()
def policy_loss(logp, logp_ref, reward, beta=0.01):
    return -(reward * logp.sum(-1)).mean() + beta * kl_penalty(logp, logp_ref)

from dataclasses import dataclass
@dataclass
class State:
    obj_xy: tuple; gripper: float; done: bool = False
def step(state: State, obs) -> State:
    state.obj_xy = detect(obs['rgb'])      # 代码估计状态
    state.gripper = obs['proprio'][-1]     # 本体感觉
    return state
def policy(s: State):
    return 'grasp' if near(s.obj_xy, s.gripper) else 'approach'

def rsi_loop(tasks, library, rounds=5):
    for _ in range(rounds):
        results = [run(library, t) for t in tasks]   # rollout
        fails = [t for t, r in zip(tasks, results) if not r]
        library = coding_agent.edit(library, fails)  # 显式可控修改
    return library

import torch
def steered_action(policy, z, dz, cond_tactile):
    # policy 冻结；只更新 dz 的生成网络
    z_steer = z + dz(z, cond_tactile)
    return policy(z_steer)   # a_t = G_theta(z_t + dz_t)

def pfr_update(F_range, obs_img, tactile_hist, vlm):
    diag = vlm.reason(obs_img, tactile_hist)      # 物理先验诊断失败
    lo, hi = F_range
    if diag == 'too_much_force': hi *= 0.8
    elif diag == 'too_little_force': lo *= 1.2
    return (lo, hi)
def enforce(F_cmd, F_range):
    return min(max(F_cmd, F_range[0]), F_range[1])

def compression_ratio(sum_len, mem_len, hist_len):
    return (sum_len + mem_len) / hist_len   # 目标：小 rho，高 joint
