import torch
import torch.nn.functional as F
def bt_loss(reward, y_w, y_l):
    r_w, r_l = reward(y_w), reward(y_l)
    return -F.logsigmoid(r_w - r_l).mean()   # -log sigmoid(r_w - r_l)

def compose_reward(pref, rubric, mode='naive', w1=0.5, w2=0.5):
    if mode == 'naive':
        return w1 * pref + w2 * rubric         # 次优：固定加权
    # 组合策略：先保 rubric 门槛，再冲偏好（示意）
    return pref if rubric > 0 else -1.0
